 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def blocks(n, separators):
        out = []
        start = 0
        for p in separators:
            if p >= start:
                if p > start:
                    out.append((start, p))
                start = p + 1
        if start < n:
            out.append((start, n))
        return out

    rb = blocks(h, sep_rows)
    cb = blocks(w, sep_cols)
    panels = []
    for r0, r1 in rb:
        for c0, c1 in cb:
            cells = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            if any(v != bg for v in cells):
                panels.append((r0, r1, c0, c1))
    if not panels:
        return [row[:] for row in grid]
    sr0, sr1, sc0, sc1 = panels[0]
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]
    out = [row[:] for row in grid]
    for r0, r1 in rb:
        for c0, c1 in cb:
            if (r1-r0, c1-c0) != (sr1-sr0, sc1-sc0):
                continue
            for dr in range(r1-r0):
                for dc in range(c1-c0):
                    out[r0+dr][c0+dc] = pattern[dr][dc]
    return out

